create table ai.models(id uuid primary key default gen_random_uuid(),alias text not null unique,role text not null,description text,enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table ai.model_versions(id uuid primary key default gen_random_uuid(),model_id uuid not null references ai.models(id) on delete cascade,source_repo text not null,source_revision text,quantization text,context_window integer check(context_window is null or context_window>0),runtime text,license text,checksum_manifest jsonb,config jsonb not null default '{}'::jsonb,status text not null default 'candidate' check(status in ('candidate','validated','eval_passed','internal','canary','partial','production','retired','blocked')),created_at timestamptz not null default now(),unique(model_id,source_repo,source_revision,quantization));
create table ai.model_deployments(id uuid primary key default gen_random_uuid(),model_version_id uuid not null references ai.model_versions(id) on delete cascade,environment text not null check(environment in ('development','preview','staging','production')),gpu_provider text,gpu_type text,gpu_count integer check(gpu_count is null or gpu_count>0),runtime text,endpoint_ref text,status text not null default 'offline' check(status in ('offline','starting','loading','ready','draining','failed','stopping')),max_context integer,max_concurrency integer,cost_per_gpu_hour numeric(12,4),last_health_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table ai.routing_rules(id uuid primary key default gen_random_uuid(),version integer not null check(version>0),task_type text not null,primary_alias text not null references ai.models(alias),fallback_alias text references ai.models(alias),escalation_alias text references ai.models(alias),enabled boolean not null default true,created_at timestamptz not null default now(),unique(version,task_type));
create table ai.prompt_versions(id uuid primary key default gen_random_uuid(),identifier text not null,version integer not null check(version>0),content text not null,model_role text,status text not null default 'draft' check(status in ('draft','eval','internal','canary','partial','production','retired')),created_by uuid references auth.users(id),activated_at timestamptz,created_at timestamptz not null default now(),unique(identifier,version));
create table ai.agent_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete cascade,engagement_id uuid references security.engagements(id) on delete set null,user_id uuid not null references auth.users(id),state ai.agent_run_state not null default 'QUEUED',objective text not null,priority smallint not null default 2 check(priority between 0 and 4),model_alias text references ai.models(alias),router_version integer,max_steps integer not null default 30 check(max_steps between 1 and 500),max_duration_seconds integer not null default 1800 check(max_duration_seconds between 1 and 86400),max_tokens bigint not null default 100000 check(max_tokens>0),max_tool_calls integer not null default 50 check(max_tool_calls>=0),max_cost numeric(12,4) not null default 25 check(max_cost>=0),current_step integer not null default 0 check(current_step>=0),error_code text,error_message text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now()); create index agent_runs_status_priority_created_idx on ai.agent_runs(state,priority,created_at); create index agent_runs_org_created_idx on ai.agent_runs(organization_id,created_at desc);
create table ai.agent_run_steps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,agent_run_id uuid not null references ai.agent_runs(id) on delete cascade,step_number integer not null check(step_number>=0),state ai.agent_run_state not null,idempotency_key text not null,attempt integer not null default 1 check(attempt>0),execution_status text not null default 'pending' check(execution_status in ('pending','running','succeeded','failed','cancelled','skipped')),observation jsonb,next_action jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(agent_run_id,step_number,attempt),unique(agent_run_id,idempotency_key));
create table ai.agent_checkpoints(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,agent_run_id uuid not null references ai.agent_runs(id) on delete cascade,step_number integer not null,current_state ai.agent_run_state not null,next_action jsonb,observation jsonb,model_version_id uuid references ai.model_versions(id),prompt_version_id uuid references ai.prompt_versions(id),tool_version text,usage_snapshot jsonb not null default '{}'::jsonb,budget_snapshot jsonb not null default '{}'::jsonb,lease_generation bigint not null default 0,created_at timestamptz not null default now(),unique(agent_run_id,step_number));
create table ai.tool_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete cascade,engagement_id uuid references security.engagements(id) on delete set null,agent_run_id uuid references ai.agent_runs(id) on delete cascade,tool_name text not null,tool_version text not null,input_schema_version text not null,idempotency_key text not null,input jsonb not null,normalized_observation jsonb,raw_artifact_file_id uuid references artifacts.files(id) on delete set null,status text not null default 'queued' check(status in ('queued','scope_validation','waiting_for_approval','running','succeeded','failed','cancelled','blocked')),sandbox_image_version text,sandbox_image_digest text,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table ai.generation_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,user_id uuid not null references auth.users(id),conversation_id uuid references app.conversations(id) on delete set null,agent_run_id uuid references ai.agent_runs(id) on delete set null,requested_role text not null,model_version_id uuid references ai.model_versions(id),routing_version integer,prompt_version_id uuid references ai.prompt_versions(id),status text not null default 'queued' check(status in ('queued','running','completed','failed','cancelled')),priority smallint not null default 1 check(priority between 0 and 4),input_tokens bigint not null default 0,output_tokens bigint not null default 0,queue_ms integer,ttft_ms integer,generation_ms integer,cost numeric(12,6) not null default 0,created_at timestamptz not null default now(),completed_at timestamptz); create index generation_status_priority_created_idx on ai.generation_requests(status,priority,created_at);
create table ai.memory_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,scope text not null check(scope in ('session','conversation','project','user','organization')),content text not null,embedding extensions.vector,source_type text not null,source_id uuid,source_content_hash text,confidence numeric(5,2) check(confidence between 0 and 100),validation_status text not null default 'candidate' check(validation_status in ('candidate','trusted','invalidated','rejected')),writer text not null default 'system',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz); create index memory_project_scope_idx on ai.memory_items(organization_id,project_id,scope) where deleted_at is null;
alter table security.findings add constraint findings_source_agent_run_fk foreign key(source_agent_run_id) references ai.agent_runs(id) on delete set null; alter table artifacts.file_chunks add constraint file_chunks_embedding_model_fk foreign key(embedding_model_version_id) references ai.model_versions(id) on delete set null;
create table security.finding_evidence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,finding_id uuid not null references security.findings(id) on delete cascade,evidence_type text not null check(evidence_type in ('screenshot','log','source_code_reference','request_response','file','agent_observation','text','image')),source_tool_run_id uuid references ai.tool_runs(id) on delete set null,source_agent_run_id uuid references ai.agent_runs(id) on delete set null,source_file_id uuid references artifacts.files(id) on delete set null,content_hash text not null,tool_version text,processing_version text,current_version integer not null default 1 check(current_version>0),created_at timestamptz not null default now()); create index evidence_finding_created_idx on security.finding_evidence(finding_id,created_at);
create table security.finding_evidence_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,evidence_id uuid not null references security.finding_evidence(id) on delete cascade,version integer not null check(version>0),content jsonb not null,content_hash text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(evidence_id,version));
insert into ai.models(alias,role,description,enabled) values ('vexonyx-small','small','Cheap classification and metadata tasks',false),('vexonyx-general','general','General chat, coding and reporting',false),('vexonyx-security','security','Authorized security reasoning',false),('vexonyx-reasoning','reasoning','Heavy escalation reasoning',false),('vexonyx-embedding','embedding','Semantic retrieval embeddings',false) on conflict(alias) do update set role=excluded.role,description=excluded.description;
insert into ai.routing_rules(version,task_type,primary_alias,fallback_alias,escalation_alias) values (1,'metadata','vexonyx-small','vexonyx-general','vexonyx-reasoning'),(1,'normal_chat','vexonyx-general','vexonyx-small','vexonyx-reasoning'),(1,'code_analysis','vexonyx-general','vexonyx-small','vexonyx-reasoning'),(1,'report','vexonyx-general','vexonyx-small','vexonyx-reasoning'),(1,'security_workflow','vexonyx-security','vexonyx-general','vexonyx-reasoning'),(1,'finding_validation','vexonyx-security','vexonyx-general','vexonyx-reasoning') on conflict(version,task_type) do update set primary_alias=excluded.primary_alias,fallback_alias=excluded.fallback_alias,escalation_alias=excluded.escalation_alias;
